阅读下面的代码（C++17）。`using Base::pub;` 让 `(1)` 能编译，但 `(2)` 仍然失败。请说明两行的结果与原因，并指出在 `D` 的成员函数内部能访问哪些基类成员。
```cpp
class Base {
public:
    int pub = 1;
protected:
    int prot = 2;
private:
    int priv = 3;
};

class D : protected Base {
public:
    using Base::pub;
    int sum() const { return pub + prot; }
};

void take(const Base&) {}

int main() {
    D d;
    std::cout << d.pub << d.sum() << std::endl;  // (1)
    take(d);                                     // (2)
}
```

